async function syncFavorite(id,isFavorite){const c=db(),u=current(),r=getRecipes().find(x=>String(x.id)===String(id));if(!c||!u?.id||!r)return;try{const row={user_id:u.id,recipe_key:String(id),recipe_title:r.name,recipe_category:r.category||'',recipe_snapshot:r,is_favorite:!!isFavorite,is_saved:!!isFavorite,updated_at:new Date().toISOString()};const {error}=await c.from('user_recipe_collections').upsert(row,{onConflict:'user_id,recipe_key'});if(error)console.warn('[TN favorites] Sincronização indisponível:',error.message)}catch(e){console.warn('[TN favorites]',e.message)}}
async function restoreRemoteFavorites(){const c=db(),u=current();if(!c||!u?.id)return;try{const {data,error}=await c.from('user_recipe_collections').select('recipe_key,is_favorite,is_saved,recipe_snapshot').eq('user_id',u.id);if(error)throw error;const set=new Set(safeRead('tn_favs',[]).map(String));(data||[]).forEach(x=>{if(x.is_favorite||x.is_saved){set.add(String(x.recipe_key));const snap=x.recipe_snapshot;if(snap&&snap.name&&!getRecipes().some(r=>String(r.id)===String(snap.id)))getRecipes().push(snap)}});safeWrite('tn_favs',[...set].map(x=>/^\\d+$/.test(x)?Number(x):x));if(typeof favorites!=='undefined'){favorites.clear();set.forEach(x=>favorites.add(/^\\d+$/.test(x)?Number(x):x));if(typeof renderFavorites==='function')renderFavorites();if(typeof renderHome==='function')renderHome()}console.info('[TN favorites] Favoritos sincronizados:',set.size)}catch(e){console.warn('[TN favorites] Não foi possível restaurar favoritos:',e.message)}}
const origRenderFavorites=window.renderFavorites;
if(typeof origRenderFavorites==='function')window.renderFavorites=function(){const result=origRenderFavorites.apply(this,arguments);const host=$('favoriteCards');if(!host||$('savedSearch'))return result;const wrap=document.createElement('div');wrap.className='tn-tool-row';wrap.innerHTML='<input id="tnFavoriteSearch" placeholder="Pesquisar receitas favoritas..." aria-label="Pesquisar favoritas"><span class="small muted">'+(typeof favorites!=='undefined'?favorites.size:0)+' salvas</span>';host.prepend(wrap);const input=$('tnFavoriteSearch');input.oninput=()=>host.querySelectorAll('.recipe-card').forEach(card=>card.style.display=norm(card.innerText).includes(norm(input.value))?'':'none');return result;};
const origToggleLike=window.toggleLike;
if(typeof origToggleLike==='function')window.toggleLike=function(id){const before=(typeof recipeStats==='function'?recipeStats(id).liked:false);const result=origToggleLike.apply(this,arguments);const after=(typeof recipeStats==='function'?recipeStats(id).liked:!before);if(before!==after)recordLike(id,after);return result;};
const origToggleFavorite=window.toggleFavorite;
if(typeof origToggleFavorite==='function')window.toggleFavorite=function(id){const before=(typeof favorites!=='undefined'&&favorites.has(id));const result=origToggleFavorite.apply(this,arguments);const after=(typeof favorites!=='undefined'&&favorites.has(id));if(before!==after){syncFavorite(id,after);if(after&&typeof favorites!=='undefined'&&favorites.size===1)awardAchievement('first_favorite',{recipe_id:String(id)});if(after&&typeof favorites!=='undefined'&&favorites.size>=5)awardAchievement('five_favorites',{count:favorites.size})}return result;};
const parseShoppingAmount=x=>{const raw=String(x.name||'').trim();const m=raw.match(/^([0-9]+(?:[.,][0-9]+)?)\s*(kg|g|mg|l|ml|unidades?|unid\.?|ovos?|dentes?|colheres?|xícaras?|xic(?:aras)?|fatias?|pacotes?|latas?)?\s+(?:de\s+)?(.+)$/i);if(m)return {name:m[3].trim(),quantity:Number(m[1].replace(',','.')),unit:(m[2]||'unidade').toLowerCase().replace(/s$/,'')};return {name:raw,quantity:Number(x.quantity)||1,unit:String(x.unit||'unidade').toLowerCase()};};
const canonicalIngredient=s=>{let v=norm(s);const pairs=[['ovos','ovo'],['tomates','tomate'],['cebolas','cebola'],['batatas','batata'],['cenouras','cenoura'],['bananas','banana'],['macas','maca'],['laranjas','laranja'],['limoes','limao'],['dentes de alho','dente de alho'],['fatias de pao','fatia de pao']];for(const [plural,singular] of pairs)if(v===plural)return singular;return v;};
const mergeShopping=items=>{const map=new Map();items.forEach(raw=>{const x={...raw},p=parseShoppingAmount(x),k=canonicalIngredient(p.name);if(!k)return;if(!map.has(k)){map.set(k,{...x,name:p.name,quantity:p.quantity,unit:p.unit});return;}const old=map.get(k);if(old.unit===p.unit)old.quantity=(Number(old.quantity)||1)+p.quantity;else{old.quantity=(Number(old.quantity)||1)+p.quantity;old.unit='unidades';}old.done=Boolean(old.done&&x.done);if(x.recipe&&!String(old.recipe||'').includes(x.recipe))old.recipe=old.recipe?old.recipe+', '+x.recipe:x.recipe;});return [...map.values()];};
const origPrepareShopping=window.prepareShopping;
if(typeof origPrepareShopping==='function')window.prepareShopping=function(id){const before=safeRead('tn_shopping',[]),result=origPrepareShopping.apply(this,arguments),created=safeRead('tn_shopping',[]),r=getRecipes().find(x=>String(x.id)===String(id));const additions=created.map(x=>({...x,quantity:Number(x.quantity)||1,unit:x.unit||'unidade',recipe:r?.name||x.recipe,recipeId:r?.id||x.recipeId}));safeWrite('tn_shopping',mergeShopping([...before,...additions]));if(typeof renderShopping==='function')renderShopping();return result;};
window.tnAddShoppingItem=function(){const input=$('tnShoppingSearch'),name=String(input?.value||'').trim();if(!name){input?.focus();return}const list=safeRead('tn_shopping',[]);if(list.some(x=>norm(x.name)===norm(name))){alert('Esse produto já está na sua lista.');return}list.push({name,quantity:1,unit:'unidade',done:false,custom:true});safeWrite('tn_shopping',mergeShopping(list));renderShopping();const next=$('tnShoppingSearch');if(next){next.value='';next.focus()}};
const origRenderShopping=window.renderShopping;
if(typeof origRenderShopping==='function')window.renderShopping=function(){const result=origRenderShopping.apply(this,arguments);const host=$('shoppingItems');if(!host)return result;const list=safeRead('tn_shopping',[]);const toolbar=document.createElement('div');toolbar.className='tn-tool-row';toolbar.style.cssText='display:flex;gap:8px;flex-wrap:wrap;margin:12px 0';toolbar.innerHTML='<input id="tnShoppingSearch" type="search" placeholder="Pesquisar ou adicionar produto..." aria-label="Pesquisar ou adicionar produto" style="flex:1;min-width:180px"><button type="button" class="btn btn-primary" onclick="tnAddShoppingItem()">+ Adicionar</button><button type="button" class="btn btn-light" onclick="tnShareShopping()">Compartilhar</button><button type="button" class="btn btn-light" onclick="tnClearBought()">Remover comprados</button><p class="small muted" style="width:100%;margin:0">Digite um produto e pressione Enter ou Adicionar. A busca também filtra os itens da sua lista.</p>';host.prepend(toolbar);const input=$('tnShoppingSearch');input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();tnAddShoppingItem()}};input.oninput=()=>{const q=norm(input.value);host.querySelectorAll('.shopping-row').forEach(row=>row.style.display=!q||norm(row.innerText).includes(q)?'':'none');let note=$('tnShoppingNoResults');if(q&&!Array.from(host.querySelectorAll('.shopping-row')).some(row=>row.style.display!=='none')){if(!note){note=document.createElement('p');note.id='tnShoppingNoResults';note.className='small muted';input.parentElement.after(note)}note.textContent='Nenhum item encontrado na lista. Pressione + Adicionar para incluir “'+input.value.trim()+'”.';}else note?.remove()};host.querySelectorAll('.shopping-row').forEach((row,i)=>{const item=list[i];const label=row.querySelector('label');if(item&&label){const qty=label.querySelector('.small.muted');if(qty)qty.textContent='('+String(item.quantity??1)+' '+String(item.unit||'unidade')+(Number(item.quantity??1)===1?'':'s')+')';}if(item?.recipe){const label=row.querySelector('label');if(label&&!label.textContent.includes(item.recipe))label.insertAdjacentHTML('beforeend',' <span class="small muted">· '+escHtml(item.recipe)+'</span>')}});return result;};
window.tnShareShopping=function(){const list=safeRead('tn_shopping',[]).filter(x=>!x.done);const text='Lista de compras — Tem na Geladeira\n'+list.map(x=>'☐ '+x.name+(x.recipe?' (para '+x.recipe+')':'')).join('\n');if(navigator.share)navigator.share({title:'Lista de compras',text}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>alert('Lista copiada.')).catch(()=>alert(text));else alert(text);};
window.tnClearBought=function(){safeWrite('tn_shopping',safeRead('tn_shopping',[]).filter(x=>!x.done));if(typeof renderShopping==='function')renderShopping();};
