/* Planejador semanal por refeição e integração segura com a lista de compras. */
const tnMealSlots=[['breakfast','Café da manhã'],['lunch','Almoço'],['dinner','Jantar'],['snack','Lanche']];
const tnPlanDays=[['mon','Segunda'],['tue','Terça'],['wed','Quarta'],['thu','Quinta'],['fri','Sexta'],['sat','Sábado'],['sun','Domingo']];
const tnRecipeHasMeasures=r=>Array.isArray(r?.ingredients)&&r.ingredients.length>=2&&!r.ingredients.some(x=>/ingrediente principal|conforme a receita|recheio escolhido|folhas ou vegetais|base de massa|outras frutas disponíveis|quantidade desejada/i.test(String(x)))&&r.ingredients.every(x=>/\d/.test(String(x))||/a gosto|pitada|para untar|para finalizar|para servir|óleo para fritar|água para cozinhar/i.test(String(x)));
const tnReadPlanV2=()=>{let p=loadPlan();if(!p||typeof p!=='object')p={week:weekStart(),days:{}};p.days=p.days&&typeof p.days==='object'?p.days:{};const days={};Object.entries(p.days).forEach(([d,v])=>{if(typeof v==='string'||typeof v==='number'){if(String(v))days[d]={lunch:{recipeId:String(v),servings:2}};}else if(v&&typeof v==='object'){const row={};Object.entries(v).forEach(([m,x])=>{if(typeof x==='string'||typeof x==='number'){if(String(x))row[m]={recipeId:String(x),servings:2};}else if(x&&(x.recipeId||x.id))row[m]={recipeId:String(x.recipeId||x.id),servings:Math.max(1,Math.min(20,Number(x.servings)||2))};});if(Object.keys(row).length)days[d]=row;}});p.days=days;p.week=p.week||weekStart();return p;};
window.renderPlanner=function(){const host=$('tnPlannerContent');if(!host)return;const p=tnReadPlanV2(),rs=getRecipes().filter(tnRecipeHasMeasures),opts='<option value="">— Não planejado —</option>'+rs.map(r=>'<option value="'+escHtml(r.id)+'">'+escHtml(r.name)+'</option>').join('');host.innerHTML='<div class="tn-enhanced-panel"><div class="tn-tool-row"><div><b>Planeje sua semana</b><div class="small muted">Escolha receitas por refeição e ajuste as porções.</div></div><button class="btn btn-light" onclick="tnPlannerShare()">Compartilhar</button><button class="btn btn-primary" onclick="tnPlannerShopping()">Gerar lista de compras</button></div><div class="tn-plan-grid tn-plan-grid-v2">'+tnPlanDays.map(([d,label])=>'<section class="tn-plan-day"><h3>'+label+'</h3>'+tnMealSlots.map(([m,ml])=>'<label class="tn-plan-slot"><span>'+ml+'</span><select aria-label="'+label+' '+ml+'" onchange="tnPlannerSet(\''+d+'\',\''+m+'\',this.value)">'+opts+'</select><span class="small muted">Porções</span><input type="number" min="1" max="20" value="'+(Number(p.days[d]?.[m]?.servings)||2)+'" aria-label="Porções '+label+' '+ml+'" onchange="tnPlannerSetServings(\''+d+'\',\''+m+'\',this.value)"></label>').join('')+'</section>').join('')+'</div><p class="small muted">A lista soma ingredientes medidos e mantém os itens que você já adicionou.</p></div>';tnPlanDays.forEach(([d,label])=>tnMealSlots.forEach(([m,ml])=>{const s=host.querySelector('select[aria-label="'+label+' '+ml+'"]');if(s)s.value=p.days[d]?.[m]?.recipeId||'';}));};
window.tnPlannerSet=async function(day,meal,id){if(arguments.length===2){id=meal;meal='lunch';}const p=tnReadPlanV2();p.days[day]=p.days[day]||{};if(id){p.days[day][meal]={recipeId:String(id),servings:Number(p.days[day][meal]?.servings)||Math.max(1,Number(getRecipes().find(x=>String(x.id)===String(id))?.servings)||2)};}else{delete p.days[day][meal];if(!Object.keys(p.days[day]).length)delete p.days[day];}savePlan(p);renderPlanner();try{const c=db(),u=current();if(c&&u?.id){const {error}=await c.from('tn_weekly_plans').upsert({user_id:u.id,week_start:p.week,plan:p},{onConflict:'user_id,week_start'});if(error)console.warn('[TN planner]',error.message)}}catch(e){console.warn('[TN planner]',e.message)}};
window.tnPlannerSetServings=function(day,meal,value){const p=tnReadPlanV2();if(!p.days[day]?.[meal])return;p.days[day][meal].servings=Math.max(1,Math.min(20,parseInt(value,10)||2));savePlan(p);};
const tnParseMeasuredLine=line=>{const raw=String(line||'').trim();const m=raw.match(/^(\d+\s+\d+\s*\/\s*\d+|\d+\s*\/\s*\d+|\d+(?:[.,]\d+)?)\s*(kg|g|mg|l|ml|unidades?|unid\.?|ovos?|dentes?|colheres?(?:\s+de\s+(?:sopa|chá))?|xícaras?|xic(?:aras)?|fatias?|pacotes?|latas?|pães?)?\s*(.*)$/i);if(!m||!m[3].trim())return null;const parts=m[1].match(/\d+/g);const q=m[1].includes('/')?(parts.length===3?Number(parts[0])+Number(parts[1])/Number(parts[2]):Number(parts[0])/Number(parts[1])):Number(m[1].replace(',','.'));if(!q||!Number.isFinite(q))return null;let unit=(m[2]||'unidade').toLowerCase().replace(/s$/,'');let name=m[3].replace(/\([^)]*\)/g,' ').replace(/^\s*(?:de|do|da|dos|das)\s+/i,'').replace(/[,\s]+$/,'').trim();return name?{name,quantity:q,unit}:null;};
const tnShoppingNorm=s=>norm(String(s||'').replace(/\([^)]*\)/g,' ').replace(/\b(cru|crua|cozido|cozida|picado|picada|ralado|ralada|descascado|descascada)\b/gi,'').replace(/^\s*(?:de|do|da|dos|das)\s+/i,'').trim());
window.tnPlannerShopping=function(){const p=tnReadPlanV2(),rs=getRecipes().filter(tnRecipeHasMeasures),map=new Map();Object.values(p.days||{}).forEach(meals=>Object.values(meals||{}).forEach(entry=>{const r=rs.find(x=>String(x.id)===String(entry.recipeId));if(!r)return;const scale=(Number(entry.servings)||Number(r.servings)||2)/(Number(r.servings)||2);(r.ingredients||[]).forEach(line=>{const x=tnParseMeasuredLine(line);if(!x)return;const key=tnShoppingNorm(x.name)+'|'+x.unit;if(!map.has(key))map.set(key,{name:x.name,quantity:0,unit:x.unit,done:false,recipe:r.name,recipeId:r.id,source:'planner'});const item=map.get(key);item.quantity+=x.quantity*scale;if(!String(item.recipe).split(', ').includes(r.name))item.recipe+=', '+r.name;} );}));const list=safeRead('tn_shopping',[]).filter(x=>x.source!=='planner');map.forEach(x=>{const i=list.findIndex(y=>tnShoppingNorm(y.name)===tnShoppingNorm(x.name)&&String(y.unit||'unidade')===x.unit);if(i<0)list.push(x);else if(list[i].source==='planner'){list[i].quantity=Number(list[i].quantity||0)+x.quantity;list[i].done=false;list[i].recipe=[...new Set(String(list[i].recipe||'').split(', ').concat(x.recipe.split(', ')))].join(', ');}else list.push(x);});safeWrite('tn_shopping',list);if(typeof go==='function')go('shopping');if(typeof renderShopping==='function')renderShopping();};


/* Ajustes finais da lista: evita barra duplicada, permite editar quantidade e remover itens. */
const tnRenderShoppingV2=window.renderShopping;
window.renderShopping=function(){const host=$('shoppingItems');if(host){const old=host.querySelector('#tnShoppingSearch');if(old?.parentElement)old.parentElement.remove();host.querySelectorAll('.tn-shopping-edit-v2').forEach(x=>x.remove());}const result=tnRenderShoppingV2.apply(this,arguments);const target=$('shoppingItems');if(!target)return result;const items=safeRead('tn_shopping',[]);target.querySelectorAll('.shopping-row').forEach((row,i)=>{const item=items[i];if(!item)return;const controls=document.createElement('div');controls.className='tn-shopping-edit-v2';controls.style.cssText='display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:4px 0 12px 28px';controls.innerHTML='<label class="small muted">Quantidade <input type="number" min="0.1" step="0.1" value="'+Math.max(.1,Number(item.quantity)||1)+'" style="width:85px" aria-label="Quantidade de '+escHtml(item.name)+'"></label><button type="button" class="btn btn-light" style="padding:5px 9px">Remover</button>';controls.querySelector('input').onchange=()=>{const list=safeRead('tn_shopping',[]);if(!list[i])return;list[i].quantity=Math.max(.1,Number(controls.querySelector('input').value)||1);safeWrite('tn_shopping',list);renderShopping();};controls.querySelector('button').onclick=()=>{const list=safeRead('tn_shopping',[]);list.splice(i,1);safeWrite('tn_shopping',list);renderShopping();};row.appendChild(controls);});return result;};


const tnV2Style=document.createElement('style');tnV2Style.textContent='.tn-plan-grid-v2{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:14px;margin-top:14px}.tn-plan-grid-v2 .tn-plan-day{min-width:0;padding:14px;border:1px solid var(--border,#e7e3dc);border-radius:14px;background:var(--card,#fff)}.tn-plan-grid-v2 .tn-plan-day h3{margin:0 0 12px}.tn-plan-slot{display:grid;grid-template-columns:1fr;gap:5px;margin:12px 0}.tn-plan-slot select,.tn-plan-slot input{width:100%;min-width:0;box-sizing:border-box}.tn-plan-slot>span:first-child{font-weight:600}.tn-plan-slot input[type=number]{max-width:100px}.tn-shopping-edit-v2 input{padding:5px;border:1px solid #d8d5cf;border-radius:8px}@media(max-width:600px){.tn-plan-grid-v2{grid-template-columns:1fr}.tn-plan-grid-v2 .tn-plan-day{padding:12px}.tn-plan-slot{margin:10px 0}}';document.head.appendChild(tnV2Style);

/* Correção de compatibilidade: ações dos botões da receita e plano semanal V2. */
window.tnStartCooking=function(id,requestedServings){
 const r=getRecipes().find(x=>String(x.id)===String(id));
 if(!r){alert('Não foi possível localizar esta receita. Atualize a página e tente novamente.');return;}
 const steps=Array.isArray(r.steps)?r.steps.filter(x=>String(x||'').trim()):[];
 const baseServings=Math.max(1,Number(r.servings)||4),servings=Math.max(1,Number(requestedServings)||baseServings),factor=servings/baseServings;
 const ingredients=Array.isArray(r.ingredients)?r.ingredients:[];
 let index=0;
 let overlay=$('tnCookOverlay');
 if(!overlay){overlay=document.createElement('div');overlay.id='tnCookOverlay';overlay.className='tn-cook-overlay';document.body.appendChild(overlay);}
 const render=()=>{
  const total=steps.length;
  overlay.innerHTML='';
  const close=document.createElement('button');close.type='button';close.textContent='✕ Fechar';close.style.alignSelf='flex-end';close.onclick=()=>overlay.remove();overlay.appendChild(close);
  const progress=document.createElement('p');progress.textContent=total?'ETAPA '+(index+1)+' DE '+total:'MODO COZINHA';overlay.appendChild(progress);
  const title=document.createElement('h1');title.textContent=r.name||'Preparar receita';overlay.appendChild(title);
  const portion=document.createElement('p');portion.textContent='Rendimento: '+servings+' porções';overlay.appendChild(portion);
  if(ingredients.length){const heading=document.createElement('h2');heading.textContent='Ingredientes';overlay.appendChild(heading);const ingredientList=document.createElement('ul');ingredients.forEach(item=>{const li=document.createElement('li');li.textContent=scaleText(item,factor);ingredientList.appendChild(li)});overlay.appendChild(ingredientList);}
  const step=document.createElement('div');step.className='tn-cook-step';step.textContent=total?steps[index]:'Esta receita ainda não possui etapas de preparo cadastradas.';overlay.appendChild(step);
  const controls=document.createElement('div');controls.className='tn-cook-controls';
  const prev=document.createElement('button');prev.type='button';prev.textContent='← Anterior';prev.disabled=index===0;prev.onclick=()=>{index=Math.max(0,index-1);render();};
  const next=document.createElement('button');next.type='button';next.textContent=total&&index===total-1?'Concluir ✓':'Próxima etapa →';next.onclick=()=>{if(!total||index>=total-1){overlay.remove();return;}index++;render();};
  controls.append(prev,next);overlay.appendChild(controls);
 };
 render();
};
window.tnAddPlan=function(id,requestedServings){
 const recipe=getRecipes().find(x=>String(x.id)===String(id));
 if(!recipe){alert('Não foi possível localizar esta receita. Atualize a página e tente novamente.');return;}
 addPage();
 const p=tnReadPlanV2();
 let target=null;
 for(const [day] of tnPlanDays){
  for(const [meal] of tnMealSlots){
   if(!p.days[day]?.[meal]){target={day,meal};break;}
  }
  if(target)break;
 }
 if(!target)target={day:'mon',meal:'lunch'};
 p.days[target.day]=p.days[target.day]||{};
 p.days[target.day][target.meal]={recipeId:String(recipe.id),servings:Math.max(1,Math.min(30,Number(requestedServings)||Number(recipe.servings)||2))};
 savePlan(p);
 go('planner');
 window.renderPlanner();
};
window.tnPlannerShare=function(){
 const p=tnReadPlanV2(),rs=getRecipes();
 const lines=['Meu cardápio semanal — Tem na Geladeira'];
 tnPlanDays.forEach(([day,label])=>{
  const meals=p.days[day]||{};
  const entries=tnMealSlots.map(([meal,name])=>{
   const entry=meals[meal];if(!entry)return null;
   const recipe=rs.find(x=>String(x.id)===String(entry.recipeId));
   return recipe?name+': '+recipe.name+' ('+(entry.servings||2)+' porções)':null;
  }).filter(Boolean);
  lines.push(label+': '+(entries.length?entries.join(' · '):'—'));
 });
 const content=lines.join('\n');
 if(navigator.share)navigator.share({title:'Meu cardápio semanal',text:content}).catch(()=>{});
 else if(navigator.clipboard)navigator.clipboard.writeText(content).then(()=>alert('Cardápio copiado para compartilhar.')).catch(()=>alert(content));
 else alert(content);
};



/* Redesign de planejamento e compras: foco em fotos, leitura rápida e uso no celular. */
let tnPlannerSelectedDay='mon';
window.renderPlanner=function(){
 const host=$('tnPlannerContent');if(!host)return;
 const p=tnReadPlanV2(),rs=getRecipes().filter(tnRecipeHasMeasures);
 if(!tnPlanDays.some(([d])=>d===tnPlannerSelectedDay))tnPlannerSelectedDay='mon';
 const day=tnPlanDays.find(([d])=>d===tnPlannerSelectedDay),dayMeals=p.days[day[0]]||{};
 const total=Object.values(p.days||{}).reduce((n,v)=>n+Object.keys(v||{}).length,0);
 const planned=tnMealSlots.filter(([m])=>dayMeals[m]).length;
 const recipeById=id=>rs.find(r=>String(r.id)===String(id));
 const mealCards=tnMealSlots.map(([meal,label])=>{
  const entry=dayMeals[meal],r=entry&&recipeById(entry.recipeId),servings=Number(entry?.servings)||Number(r?.servings)||2;
  const photo=r?(typeof recipeIcon==='function'?recipeIcon(r):'🍽️'):'🍽️';
  const options='<option value="">Escolher receita</option>'+rs.map(x=>'<option value="'+escHtml(x.id)+'" '+(String(x.id)===String(entry?.recipeId)?'selected':'')+'>'+escHtml(x.name)+'</option>').join('');
  return '<article class="tn-meal-card"><div class="tn-meal-photo '+(r?'has-recipe':'')+'">'+photo+'</div><div class="tn-meal-content"><div class="tn-meal-heading"><b>'+label+'</b>'+(r?'<span class="tn-meal-status">Planejado</span>':'<span class="tn-meal-status is-empty">A escolher</span>')+'</div>'+(r?'<strong class="tn-meal-recipe">'+escHtml(r.name)+'</strong><div class="tn-meal-meta">'+escHtml(r.time||'')+' · '+servings+' porções</div>':'<p class="tn-meal-placeholder">Adicione uma receita para esta refeição.</p>')+'<select aria-label="Receita para '+label+'" onchange="tnPlannerSet(\''+day[0]+'\',\''+meal+'\',this.value)">'+options+'</select>'+(r?'<label class="tn-servings-control">Porções <input type="number" min="1" max="30" value="'+servings+'" onchange="tnPlannerSetServings(\''+day[0]+'\',\''+meal+'\',this.value)"></label>':'')+'</div></article>';
 }).join('');
 host.innerHTML='<div class="tn-planner-v3"><div class="tn-planner-summary"><div><span class="tn-eyebrow">SEU CARDÁPIO</span><h2>Planeje sua semana</h2><p>Escolha um dia e organize cada refeição.</p></div><div class="tn-plan-counter"><b>'+total+'</b><span>refeições<br>planejadas</span></div></div><div class="tn-day-tabs" role="group" aria-label="Dias da semana">'+tnPlanDays.map(([d,label])=>'<button type="button" class="'+(d===day[0]?'active':'')+'" onclick="tnPlannerChooseDay(\''+d+'\')">'+label.slice(0,3)+(Object.keys(p.days[d]||{}).length?'<i>'+Object.keys(p.days[d]).length+'</i>':'')+'</button>').join('')+'</div><div class="tn-selected-day-head"><div><h3>'+day[1]+'</h3><span>'+planned+' de 4 refeições planejadas</span></div><button class="btn btn-light" onclick="tnPlannerShare()">Compartilhar</button></div><div class="tn-meal-list">'+mealCards+'</div><div class="tn-planner-footer"><div><b>Lista de compras</b><p>Junte os ingredientes de todas as refeições planejadas.</p></div><button class="btn btn-primary" onclick="tnPlannerShopping()">Gerar lista de compras</button></div></div>';
};
window.tnPlannerChooseDay=function(day){tnPlannerSelectedDay=day;renderPlanner();};
window.renderShopping=function(){
 const host=$('shoppingItems');if(!host)return;
 const items=safeRead('tn_shopping',[]);
 const done=items.filter(x=>x.done).length,total=items.length,pct=total?Math.round(done/total*100):0;
 const categoryOf=name=>{const n=norm(name);if(/tomate|cebola|alho|batata|cenoura|banana|maca|limao|laranja|cheiro verde|alface|fruta|legume|verdura|piment/.test(n))return 'Hortifruti';if(/frango|carne|peixe|presunto|linguica|bacon/.test(n))return 'Carnes e proteínas';if(/leite|queijo|iogurte|manteiga|creme de leite|requeijao/.test(n))return 'Laticínios';if(/arroz|feijao|farinha|acucar|sal|oleo|macarrao|massa|aveia|fermento|milho|cafe/.test(n))return 'Mercearia';if(/ovo/.test(n))return 'Ovos';return 'Outros';};
 const groups=new Map();items.forEach((x,i)=>{const c=categoryOf(x.name);if(!groups.has(c))groups.set(c,[]);groups.get(c).push({x,i});});
 const order=['Hortifruti','Carnes e proteínas','Laticínios','Ovos','Mercearia','Outros'];
 const groupHtml=order.filter(c=>groups.has(c)).map(c=>'<section class="tn-shop-category"><h3>'+c+' <span>'+groups.get(c).length+'</span></h3>'+groups.get(c).map(({x,i})=>'<div class="tn-shop-item '+(x.done?'is-done':'')+'"><label><input type="checkbox" '+(x.done?'checked':'')+' onchange="toggleShopping('+i+',this.checked)"><span class="tn-shop-check"></span><span class="tn-shop-name">'+escHtml(x.name)+'</span></label><div class="tn-shop-controls"><span>'+escHtml(String(x.quantity??1))+' '+escHtml(x.unit||'unidade')+'</span><button type="button" aria-label="Editar quantidade de '+escHtml(x.name)+'" onclick="tnEditShopping('+i+')">Editar</button><button type="button" aria-label="Remover '+escHtml(x.name)+'" onclick="tnRemoveShopping('+i+')">×</button></div>'+(x.recipe?'<small>Para: '+escHtml(x.recipe)+'</small>':'')+'</div>').join('')+'</section>').join('');
 host.innerHTML='<div class="tn-shopping-v3"><div class="tn-shopping-progress"><div class="tn-shopping-progress-top"><div><span class="tn-eyebrow">NO MERCADO</span><h2>Sua lista de compras</h2><p>'+done+' de '+total+' itens comprados</p></div><b>'+pct+'%</b></div><div class="tn-progress-track"><span style="width:'+pct+'%"></span></div></div><div class="tn-shop-toolbar"><input id="tnShoppingSearch" type="search" placeholder="Buscar ou adicionar produto..." aria-label="Buscar ou adicionar produto"><button class="btn btn-primary" onclick="tnAddShoppingItem()">+ Adicionar</button></div><div class="tn-shop-actions"><button type="button" onclick="tnShareShopping()">Compartilhar lista</button><button type="button" onclick="tnClearBought()">Remover comprados</button></div>'+(total?'<div class="tn-shop-groups">'+groupHtml+'</div>':'<div class="tn-shop-empty"><div>🛒</div><b>Sua lista está vazia</b><p>Adicione ingredientes pelas receitas ou monte sua lista manualmente.</p></div>')+'</div>';
 const search=$('tnShoppingSearch');if(search){search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();tnAddShoppingItem();}};search.oninput=()=>{const q=norm(search.value);host.querySelectorAll('.tn-shop-item').forEach(row=>row.style.display=!q||norm(row.innerText).includes(q)?'':'none');host.querySelectorAll('.tn-shop-category').forEach(section=>section.style.display=Array.from(section.querySelectorAll('.tn-shop-item')).some(row=>row.style.display!=='none')?'':'none');};}
};
window.tnEditShopping=function(i){const list=safeRead('tn_shopping',[]),item=list[i];if(!item)return;const value=prompt('Quantidade de '+item.name+':',String(item.quantity??1));if(value===null)return;const quantity=Number(String(value).replace(',','.'));if(!Number.isFinite(quantity)||quantity<=0){alert('Informe uma quantidade válida.');return;}list[i].quantity=quantity;safeWrite('tn_shopping',list);renderShopping();};
window.tnRemoveShopping=function(i){const list=safeRead('tn_shopping',[]);list.splice(i,1);safeWrite('tn_shopping',list);renderShopping();};
const tnPlannerShoppingBase=window.tnPlannerShopping;
window.tnPlannerShopping=function(){tnPlannerShoppingBase();renderShopping();};
